# Generated by build.py from recipe.yml for recipe mqtt5-publish-and-subscribe. Do not edit.
Set-Location $PSScriptRoot
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--allow-anonymous', '--mqtt5-disconnect-after-retained', '--topic', '"home/#;retain"', 'mqtt5://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -d 71 mqtt5://127.0.0.1:8080/home/kitchen/temp --next mqtt5://127.0.0.1:8080/home/kitchen/temp } finally { Stop-Process $server0 }
